public sealed class CustomerOrdersRow
{
    public int Id { get; set; }

    public string Name { get; set; } = "";

    public decimal Total { get; set; }

    public DateTime? OrderDate { get; set; }
}

public static class CustomerOrdersQuery
{
    public const string Sql = """
        SELECT c.Id, c.Name, o.Total, o.OrderDate
        FROM dbo.Customers c
        JOIN dbo.Orders o ON o.CustomerId = c.Id
        WHERE c.Id = @customerId AND o.Total > @minTotal
        ORDER BY o.OrderDate DESC
        """;

    public static async Task<IReadOnlyList<CustomerOrdersRow>> CustomerOrdersAsync(this SqlConnection db, int customerId, decimal minTotal, CancellationToken ct = default)
    {
        await using var cmd = db.CreateCommand();
        cmd.CommandText = Sql;
        cmd.Parameters.AddWithValue("@customerId", customerId);
        cmd.Parameters.AddWithValue("@minTotal", minTotal);
        if (db.State != ConnectionState.Open) await db.OpenAsync(ct);
        await using var r = await cmd.ExecuteReaderAsync(ct);
        var list = new List<CustomerOrdersRow>();
        while (await r.ReadAsync(ct))
        {
            list.Add(new CustomerOrdersRow
            {
                Id = r.GetInt32(0),
                Name = r.GetString(1),
                Total = r.GetDecimal(2),
                OrderDate = r.IsDBNull(3) ? null : r.GetDateTime(3),
            });
        }
        return list;
    }
}

